{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "The closest analogue (Morgan 0.9014), a phenylethanoid glycoside nearly identical to the query, was detected in rat hippocampus and striatum after oral administration, directly demonstrating in vivo BBB passage.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A closely related phenylethanoid glycoside (Morgan 0.7671) also crossed the BBB and was detected in rat brain regions after oral dosing, supporting CNS access for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Salidroside, a simpler phenylethanoid glycoside, was present in rat hippocampal tissue 3–4 h after oral administration, providing additional class-level evidence that phenylethanoid glycosides can achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A structurally distant polyphenolic ester (DIFEQ, Morgan 0.3537) showed very low brain uptake in mice, but its low similarity to the query limits transferability and does not override the direct phenylethanoid glycoside evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct in vivo evidence from closely related phenylethanoid glycosides, especially the Morgan 0.90 analogue detected in rat brain after oral dosing, outweighs the unfavorable passive-diffusion prior and supports meaningful CNS access for the query.",
  "evidence_gaps": [
    "No quantitative brain/plasma ratio or unbound brain concentration was reported for the closest analogues.",
    "Efflux transporter involvement was not directly quantified for the query or closest analogues.",
    "Human CNS exposure data are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

